// Internal CPU benchmark; does not include browser drawing, IndexedDB or a large world graph.
(async()=>{const {spawnActors,advanceEncounter}=await import('../outbreak-simulation.mjs');const fixture=await require('../tests/outbreak-fixture.cjs')('brooms');const rows=[];for(const count of [6,24,48,96]){let w=fixture.world;for(const [type,team]of [['zombies','undead'],['brains','living']]){const instance=fixture.board.instances.find(i=>fixture.board.cards[i.cardId+'@1'].type===type);let remaining=count/2-3;while(remaining){const n=Math.min(32,remaining);w=spawnActors(w,fixture.board,fixture.graph,instance.instanceId,n);remaining-=n;}}const durations=[];for(let t=0;t<40;t++){const start=performance.now();w=advanceEncounter(w,fixture.graph,.25);durations.push(performance.now()-start);}durations.sort((a,b)=>a-b);rows.push({actors:count,graphNodes:Object.keys(fixture.graph.nodes).length,medianMs:+durations[20].toFixed(2),p95Ms:+durations[38].toFixed(2),maxMs:+durations[39].toFixed(2),savedWorldKB:Math.round(JSON.stringify(w).length/1024)});}console.log(JSON.stringify({scope:'Two generated connected tiles; 40 fixed steps per case; local Node CPU only, not a browser FPS or global-world capacity claim.',rows},null,2));})();
